        for (const v of __game.vets) v.cool = 99; for (let i = 0; i < 45; i++) __game.tick(0.05);
        const v = __game.vets[0], p = __game.player; v.cx = p.x + 12; v.cy = p.y + 12; __game.tick(0.001);
