    ok(seq.level === 4 && seq.up.speed === 2 && seq.up.slow === 1 && seq.up.bone === 0, `3 fases, 3 reforços: a Fase 4 começa com Patas ligeiras 2 e Carrocinha lenta 1 (${JSON.stringify(seq.up)})`);
