    const b0 = await bar({}), b1 = await bar({ shield: 8 }), b2 = await bar({ shield: 8, ice: 3 }), b3 = await bar({ ice: 2.5, magnet: 12 }), b4 = await bar({ shield: 8, ice: 3, turbo: 5, magnet: 12 }), b5 = await bar({});
