      const e2 = __game.exit, [hx, hy] = arrowAt(e2.x + e2.w / 2, e2.y + e2.h / 2);
      out.openState = __game.state; out.greenOpen = __fx.count(hx, hy, 12 * sx, GREEN, 20); out.noBone = __game.items.filter((i) => i.bone && !i.taken).length;
