        for (const b of K.L().blocks) { const [ac, ar] = b.from, [bc, br] = b.to, [bw, bh] = b.size || [1, 1]; for (let c = Math.min(ac, bc); c <= Math.max(ac, bc) + bw - 1; c++) for (let r = Math.min(ar, br); r <= Math.max(ar, br) + bh - 1; r++) s.add(c + "," + r); }
