        __game.freezeVets = true; __game.catsThaw = false; __game.noCatch = true;
        if (!o.keepLife) for (const it of __game.items) it.life = false;
        if (!o.keepAgents) for (const a of [...__game.vets, ...__game.cats]) { a.cx = -1000; a.cy = -1000; }
