      put(list) { __game.balls = list.map((p, i) => ({ x: p[0], y: p[1], vx: p[2] || 0, vy: p[3] || 0, taken: false, hue: p[4] ?? i % 4 })); return __game.balls; },
      dog(x, y) { __game.player.x = x - 12; __game.player.y = y - 12; },
