          if (good && o.wall && !K.solid(c + d[0] * (ahead + 1), r + d[1] * (ahead + 1))) good = false;
          if (good && o.sideWalls && (!K.solid(c + d[1], r + d[0]) || !K.solid(c - d[1], r - d[0]))) good = false; // (corredor de 1 tile: paredes dos dois lados de B)
