        for (let k = 0; k < A.d.length; k += 4) if (Math.abs(A.d[k] - bg.d[k]) + Math.abs(A.d[k + 1] - bg.d[k + 1]) + Math.abs(A.d[k + 2] - bg.d[k + 2]) > 60) diff++;
