        K.setup(id); const t = K.line(d, 2, ahead); if (!t) { out.push({ id, di, none: true, ahead }); continue; }
        const [bx, by] = K.ctr(...t); K.put([[bx, by]]); K.dog(bx - d[0] * 64, by - d[1] * 64);
        let prev = Infinity, up = 0, stop = null, side = 0, f = 0;
